 "content": "from collections import Counter


def transform(grid):
    """Keep coherent rectangular regions; erase isolated annotation marks.

    The demos establish that the large filled regions survive unchanged, while
    sparse stray colored cells in the background and anomalous cells embedded
    in a solid rectangle are removed/repaired.
    """
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not pts:
            continue
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        area = (r1-r0+1)*(c1-c0+1)
        # Only compact, near-solid rectangles are objects; their holes/noise
        # are reconstructed as their dominant color.
        if area >= 6 and len(pts) / area >= 0.55:
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    out[r][c] = color
    return out
